const int potPin = A0;

void setup() {
  Serial.begin(9600);
}

void loop() {
  int rawValue = analogRead(potPin);         // 10-bit ADC conversion (0 to 1023)
  float voltage = rawValue * (5.0 / 1023.0); // Convert count to true voltage

  Serial.print("ADC: ");
  Serial.print(rawValue);
  Serial.print(" | Voltage: ");
  Serial.print(voltage, 2);
  Serial.println(" V");
  delay(200);
}
```

The Uno's 10-bit Successive Approximation ADC provides $2^{10} = 1024$ measurement steps (~4.88 mV per step)!
